{
  "aggregate_id": "DEF-NRS-486-057::trimobile",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "contradicted",
      "reason": "The contract describes human-powered devices, which the incorporated vehicle definition excepts, so they cannot satisfy the required motor-vehicle condition."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The bus contract specifies passenger capacity but does not rule out three wheels, handlebars and a saddle seat."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than the motor vehicle required by the definition."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing does not settle whether a vehicle satisfies the required wheel, propulsion and equipment conditions."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "contradicted",
      "reason": "The incorporated motor-vehicle definition expressly excludes electric bicycles, so three wheels and a saddle do not establish eligibility."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "contradicted",
      "reason": "The incorporated motor-vehicle definition expressly excludes electric scooters, regardless of their wheel count or seating."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not determine whether the required wheel, propulsion and equipment conditions are met."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting function stated in the contract does not preclude three wheels, handlebars and a saddle seat."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The contract permits two- and three-wheeled mopeds without settling the required equipment, and the trimobile definition does not exclude mopeds."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The class contract does not determine whether members have the required three wheels, handlebars and saddle seat."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The contract permits both two- and three-wheeled motorcycles, while the equipment requirements and sidecar exception prevent a class-wide determination."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official service and identifying equipment do not settle the required wheel, propulsion and seating conditions."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person, not the motor vehicle required by the definition."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a motor vehicle."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The incorporated motor-vehicle definition requires a vehicle not operated upon rails, which rules out the on-track equipment described by the contract."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School-passenger designation and markings do not establish that every member lacks the required three wheels, handlebars or saddle seat."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Passenger-for-hire use and identifying markings do not settle whether the trimobile requirements are met."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Neither the tour or shuttle function nor the lengthened passenger-vehicle contract rules out the required three wheels, handlebars and saddle seat."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The contract includes combinations and does not establish that every member lacks a power-driven wheel or otherwise fails the trimobile requirements."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public-transit service and identifying livery do not rule out the required three wheels, handlebars and saddle seat."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A goods-carrying body does not settle whether a motor vehicle has the required three wheels, handlebars and saddle seat."
    }
  ]
}

